"""One-time, source-authored additions. No question-bank input."""
from pathlib import Path
import sys, copy, json
HERE=Path(__file__).resolve().parent
NOTES=HERE.parent
sys.path.insert(0,str(NOTES))
import build
from model import p,block,ref
parts=copy.deepcopy(build.PARTS)
findings=[]
def sec(n,key):return next(s for s in parts[n]['sections'] if s['id']==key)
def add(code,n,key,title,en,points,refs,impact,kind='list'):
    sec(n,key)['blocks'].append(block(title,en,points,refs,kind))
    findings.append(dict(id=code,part=n,section=key,title=title,impact=impact,priority='P1' if kind!='reference' else 'P2',action='added',refs=refs,status='closed'))

add('O01',1,'money-laundering','理解：處理財產與上游罪行的證明','Understand: dealing with property and proof of predicate crime',[
 ('2022年報告第3.3段說明，第405／455章第25條的洗錢罪涉及「處理」財產，以及明知或有合理理由相信財產代表犯罪得益。處理包括收受、取得、隱藏、掩飾、處置、轉換、運入香港或調離香港，以及用作借貸或保證；並不限於替別人轉帳。','Paragraph 3.3 of the 2022 report describes the section 25 DTROP/OSCO offence through dealing with property and knowing or having reasonable grounds to believe it represents crime proceeds. Dealing includes receiving, acquiring, concealing, disguising, disposing of, converting, bringing into/removing from Hong Kong, and using property to borrow or as security; it is not confined to transferring funds for others.'),
 ('控方無須證明某項上游可公訴罪行、具體行為或販毒行為曾經發生，亦無須證明該財產的確是該等犯罪得益。這不表示免除證明處理行為及上述知情／合理理由相信的要件。原文解釋，境外上游罪行及多層轉換可令來源難以證明。','The prosecution need not prove commission or specific conduct of the predicate indictable offence or drug trafficking, or that the property actually is such proceeds. This does not dispense with proving the dealing and knowledge/reasonable-grounds-to-believe elements. The report explains the difficulty of proving overseas predicates and origins obscured by multiple transformations.'),
],[ref('25','2022年版，第3.3段及註37–39','2022 edition, ¶3.3 and notes 37–39','It is not necessary for the prosecution to prove')],'避免誤以為未查明上游罪行便不可能構成洗錢。')

add('O02',1,'legal-framework','參考：限制、沒收與恐怖分子財產凍結','Reference: restraint, confiscation and terrorist-property freezing',[
 ('2022年報告把限制財產與沒收／充公分開：第3.15段舉已展開刑事法律程序時，向原訟法庭申請限制可變現財產；定罪後可向原訟法庭或區域法院申請沒收。原訟法庭亦可向潛逃者或死者發出沒收令，不能理解為一律必須先把當事人定罪。限制的可變現財產亦不必本身與所控罪行相連。','The 2022 report distinguishes restraint from confiscation/forfeiture. Paragraph 3.15 describes applying to the Court of First Instance to restrain realisable property where criminal proceedings have been instituted, and confiscation by that Court or the District Court following conviction. The Court of First Instance may also order confiscation against absconders or deceased persons, so personal conviction is not an invariable prerequisite. Restrained realisable property need not itself be connected to the offences.'),
 ('同段的不同制度不可混算：OSCO指明罪行定罪後的沒收涉及得益≥100,000港元；DTROP販毒罪行可涉及任何金額。DTROP第24D條另有民事充公機制，針對輸入／輸出時被扣押、金額>125,000港元且屬販毒得益或曾用／擬用於販毒的現金。這是2022年報告中的資產追討制度說明，不是MSO的CDD或跨境申報門檻，也不是所有沒收權力的完整清單。','The regimes in that paragraph have different conditions: post-conviction OSCO confiscation for a specified offence concerns proceeds ≥HK$100,000; DTROP drug-trafficking proceeds may be of any amount. DTROP section 24D separately provides civil forfeiture of cash >HK$125,000 seized/detained on import/export that represents drug-trafficking proceeds or was used/intended for drug trafficking. These are asset-recovery descriptions in the 2022 report, not MSO CDD or cross-boundary declaration thresholds or an exhaustive list of confiscation powers.'),
 ('UNATMO下，保安局局長可指示凍結懷疑恐怖分子財產；原訟法庭可命令充公恐怖主義行為所得、曾用或擬用於資助／協助該行為的財產。2018年增訂的全面凍結條款另禁止處理指明恐怖分子財產及指明恐怖分子／聯繫者的財產。不要把MSO的風險決定、局長的凍結權與法院的充公命令當成同一權力。','Under UNATMO the Secretary for Security may direct freezing of suspected terrorist property; the Court of First Instance may order forfeiture of property derived from a terrorist act or used/intended to finance or assist it. The blanket freezing provision introduced in 2018 separately prohibits dealing with specified terrorist property and property of specified terrorists/associates. An MSO risk decision, the Secretary’s freezing power and a court forfeiture order are different powers.'),
],[ref('25','2022年版，第3.15–3.19、4.50段及註95','2022 edition, ¶3.15–3.19, 4.50 and note 95','Restraint and confiscation/forfeiture')],'補法律工具的用途與限制；追討細節置於參考層。','reference')

add('O03',7,'reporting-duty','理解：情報分析、調查與檢控各有角色','Understand: intelligence analysis, investigation and prosecution',[
 ('按2022年報告，聯合財富情報組（JFIU，Joint Financial Intelligence Unit）由警務處及海關共同運作，接收、分析和發布可疑交易報告（STR）情報。收到報告後會按可疑程度、嚴重性及風險分析，再發展或轉交有價值情報予調查單位／其他機構；提交STR不等於已證明犯罪或必然提出檢控。','The 2022 report describes the Joint Financial Intelligence Unit (JFIU), jointly operated by the Police and Customs, as receiving, analysing and disseminating suspicious transaction report (STR) intelligence. It assesses suspicion, severity and risk, then develops or disseminates valuable intelligence to investigative units/other agencies. Filing an STR does not establish crime or guarantee prosecution.'),
 ('律政司刑事檢控科的檢控考慮是：證據顯示有合理機會定罪，並且檢控符合公眾利益；決定須獨立作出。這與本節「知悉或懷疑」便須盡快披露的責任不同，MSO不能等到掌握足以定罪的證據才報告。','The Department of Justice Prosecutions Division considers whether evidence shows a reasonable prospect of conviction AND prosecution is in the public interest, making decisions independently. This differs from the knowledge-or-suspicion disclosure duty described above; an MSO must not wait for evidence sufficient to convict before reporting.'),
 ('STR數量也不是犯罪宗數。2022年報告指出數量受合規文化、報告質素及把多名嫌疑人／多個帳戶／多宗交易放入同一份大型報告等因素影響。學習重點是提供有用資料與可疑理由，不是把歷年STR升跌直接解作犯罪升跌。','STR totals are not crime counts. The 2022 report links volumes to compliance culture, report quality and large reports combining multiple suspects, accounts and transactions. The learning point is useful information and reasons for suspicion, rather than equating historical STR changes with changes in crime.'),
],[ref('25','2022年版，第3.38–3.39、3.46–3.47段','2022 edition, ¶3.38–3.39, 3.46–3.47','reasonable prospect of conviction'),ref('03','第7.1、7.12段','¶7.1, 7.12','as soon as it is reasonable')],'避免把舉報門檻誤當刑事定罪門檻。')

add('O04',7,'law-enforcement','參考：跨境情報與正式法律協助','Reference: cross-border intelligence and formal legal assistance',[
 ('2022年報告所述埃格蒙特組織（Egmont Group）是各地財富情報單位（FIU）合作的網絡，支援跨境情報交換。JFIU依OSCO、DTROP及UNATMO有權交換情報，香港一方不以事先簽訂諒解備忘錄（MOU）為必要條件；若對方司法管轄區法律要求，則會考慮簽訂。','The 2022 report describes the Egmont Group as a network of financial intelligence units (FIUs) supporting cross-border intelligence exchange. JFIU can exchange information under OSCO, DTROP and UNATMO without an MOU being a prerequisite on the Hong Kong side; it will consider one if the counterpart jurisdiction’s law requires it.'),
 ('情報交換並不等於刑事事宜相互法律協助（MLA）：正式取證、搜查及執行境外沒收等須依適用法律協助框架處理。第25份第3.55段另說明，MLAO及FOO不適用於中國內地、澳門及台灣；當時可循法院請求書及《證據條例》處理取證／提交文件等，不能把一般境外程序一概套用。這是2022年報告的制度背景。','Intelligence exchange is distinct from mutual legal assistance in criminal matters (MLA): formal evidence-taking, searches and enforcement of external confiscation orders follow applicable legal frameworks. Paragraph 3.55 separately states that the Mutual Legal Assistance in Criminal Matters Ordinance (MLAO) and Fugitive Offenders Ordinance (FOO) do not apply to the Mainland, Macao or Taiwan; the report describes court letters of request and the Evidence Ordinance for evidence-taking/document production. Do not apply a single overseas procedure indiscriminately. This is the 2022 report’s institutional background.'),
],[ref('25','2022年版，第3.49–3.57段','2022 edition, ¶3.49–3.57','Financial intelligence exchange')],'說清情報合作與司法程序的分別；不背機構人數及協議數。','reference')

add('O05',6,'remittances','理解：跨境申報不等於證明資金合法','Understand: a cross-boundary declaration does not establish lawful funds',[
 ('2022年報告第4.55–4.56段指出，海關會從已申報及違規個案兩方面分析洗錢；報告中的不少申報違規並沒有被懷疑涉及洗錢。反過來，現金運送人即使按申報制度行事，多次把不清楚來源的現金帶到香港再經MSO兌換，仍有較高風險。申報是否合規、來源是否合理及是否需要STR，是不同問題。','Paragraphs 4.55–4.56 of the 2022 report describe Customs analysing both declarations and non-compliance cases for ML; many declaration breaches described were not suspected ML. Conversely, repeated cash carriage into Hong Kong for MSO exchange without full knowledge of its source remains a higher-risk pattern, even where declarations are made. Declaration compliance, a reasonable source explanation and the need for an STR are distinct questions.'),
],[ref('25','2022年版，第4.55–4.56段','2022 edition, ¶4.55–4.56','individual cash couriers repeatedly carry cash')],'避免把已申報視為資金來源或合法性的證明。')

add('O06',6,'monitoring','辨認：2022年報告列出的帳戶及轉移模式','Recognise: account and transfer patterns in the 2022 report',[
 ('第4.63段列出的七類觀察包括：(1)開戶後隨即更換公司董事／股東；(2)收到一筆或數筆騙款後便停用帳戶；(3)開戶後不久改變裝置識別碼／互聯網規約地址（IP address）；(4)可疑客戶共用裝置識別碼／IP地址。重點是實際使用者、控制權及活動是否與原有客戶資料相符。','The seven observations in paragraph 4.63 include: (1) changes of company directors/shareholders soon after account opening; (2) abandoning accounts after one/few fraudulent receipts; (3) changing device identity/Internet Protocol (IP) address soon after opening; (4) suspicious customers sharing device identity/IP addresses. Consider whether actual users, control and activity match the customer information.'),
 ('其餘三類是：(5)主要以轉數快（FPS，Faster Payment System）或其他網上支付平台轉移資金；(6)改用加密貨幣處置懷疑犯罪得益；(7)海外詐騙仍主要利用傳統銀行帳戶。這是2022年報告的犯罪模式觀察，不是說使用FPS、加密貨幣或傳統銀行本身便屬可疑或違法。','The other three are: (5) moving funds mainly via the Faster Payment System (FPS) or other online payment platforms; (6) using cryptocurrency to dispose of suspected proceeds; (7) continuing dominance of traditional bank accounts in overseas fraud cases. These are criminal-pattern observations in the 2022 report, not a claim that using FPS, cryptocurrency or traditional banks is itself suspicious or unlawful.'),
 ('第4.64段另列暫存款項、大額交易、交易與客戶背景不相稱、大額現金、非本地居民個人帳戶及無商業目的交易等舉報指標。須結合交易背景及解釋判斷，不能把報告的歷史舉報排序當成考試權重或機械化定罪規則。','Paragraph 4.64 also lists temporary holding of funds, large transactions, transactions inconsistent with customer background, large cash transactions, non-resident personal accounts and transactions without a business purpose as reported indicators. Assess context and explanations; the historical reporting order is neither exam weighting nor a mechanical conviction rule.'),
],[ref('25','2022年版，第4.62–4.64段','2022 edition, ¶4.62–4.64','Common Device identity')],'補齊原文七類觀察，避免僅記零散例子。')

add('O07',1,'risk-assessment','例子：保險、物業及專業服務如何被濫用','Examples: misuse of insurance, property and professional services',[
 ('2022年報告的保險例子：犯罪得益購買保險後提取款項，取得看似正常的保險公司支票，可用作分層；長期持有人壽保單或變額年金則可用作整合。報告指出，當時香港在分層階段購買保險並不常見，而整合階段較多；這不是說任何保險付款都可豁免來源審查。','The 2022 report gives insurance examples: buying insurance with proceeds and withdrawing to obtain an apparently normal insurer cheque can serve layering; holding life policies or variable annuities for longer can serve integration. It notes insurance purchases for layering were not typical in Hong Kong at the time, with more observed for integration. This does not make every insurance payment exempt from source scrutiny.'),
 ('物業交易耗時及成本較高，報告指當時在存放／分層階段購買物業並不常見，但可用分層後的得益購買物業以整合財富。合法資產或正式買賣文件，不會自動清除先前的犯罪來源。','Property transactions take time and incur costs; the report says purchases for placement/layering were unusual at the time, while proceeds after layering could purchase property for integration. A lawful asset or formal sale documentation does not automatically cleanse the prior criminal origin.'),
 ('專業服務的風險不限於專業人士知情合謀：犯罪分子可提供偽造文件讓會計師核數，利用律師代管聲稱來自合法業務／投資的款項，或利用TCSP成立公司、擔任公司秘書／受託人及協助開戶。應理解服務如何掩蓋真實活動，不能單憑有會計師、律師或公司秘書參與便視為資金合法。','Risk does not require knowing collusion by a professional: criminals may supply forged documents for accountants to audit, use lawyers as escrow agents for purported business/investment money, or use TCSPs for company formation, secretarial/trustee services and account-opening assistance. Understand how services may obscure the activity; professional involvement alone does not establish lawful funds.'),
],[ref('25','2022年版，第4.45–4.51段','2022 edition, ¶4.45–4.51','Purchase of insurance products')],'補可理解的跨行業機制，不擴成其他行業操作手冊。')

add('O08',6,'beneficial-owners','認識：重要控制人登記冊及CDD的關係','Recognise: the significant controllers register and CDD',[
 ('2022年報告介紹重要控制人登記冊（SCR，Significant Controllers Register）：香港成立的公司須識別並保存重要控制人資料，上市公司獲豁除並另受證券法的披露規定約束。SCR由公司在註冊辦事處或香港訂明地點備存及更新，供執法人員依法查閱／複印；它不是把所有實益擁有人資料公開放在公司註冊處查冊系統。','The 2022 report describes the Significant Controllers Register (SCR): Hong Kong-incorporated companies identify and maintain significant-controller information; listed companies are exempt and subject to separate securities-law disclosure requirements. The company keeps and updates its SCR at its registered office or a prescribed Hong Kong place, making it available for lawful law-enforcement inspection/copying. This does not put all beneficial-owner details on the public Companies Registry search system.'),
 ('第7.24段列五種擇一控制條件：直接／間接持有>25%已發行股份；直接／間接持有>25%表決權；直接／間接有權委任或罷免過半數董事；有權或實際對公司行使重大影響力／控制；或對非屬法人的信託／商號活動有上述重大影響力／控制，而其受託人／成員就該公司符合前四項任何一項。>25%包括25.1%，不包括恰好25%；恰好25%仍可能符合其他控制條件。','Paragraph 7.24 gives five alternative control conditions: directly/indirectly holding >25% of issued shares; directly/indirectly holding >25% of voting rights; directly/indirectly having the right to appoint/remove a majority of directors; having the right to exercise or actually exercising significant influence/control over the company; or such influence/control over a trust/firm that is not a legal person, whose trustees/members meet any of the first four conditions for the company. >25% includes 25.1%, but not exactly 25%; exactly 25% may still meet another control condition.'),
 ('重要控制人包括最終有重大控制權的須登記人士（自然人或指明實體），以及有重大控制權且為公司成員的須登記法律實體（可在香港或境外成立）。因此SCR內可列法人，不能把它直接等同MSO須追查的所有自然人實益擁有人名單。公司須識別、核實及記錄最終控制自然人和中間法律實體的資料。','Significant controllers include registrable persons (natural persons or specified entities with ultimate significant control) and registrable legal entities with significant control that are members of the company, whether incorporated in Hong Kong or elsewhere. An SCR can therefore contain legal entities; it is not simply identical to the natural-person beneficial owners an MSO must trace. Companies identify, verify and record ultimate controlling individuals and intermediate legal entities.'),
 ('公司須指定代表協助執法人員：可為通常所述居於香港的自然人成員／董事／僱員，或會計專業人士、法律專業人士、持牌TCSP。報告說明執法機構依法查閱SCR無須先取得法庭命令；這項執法權不等於MSO有相同查閱權。','A company designates a representative to assist law enforcement: a member/director/employee who is a natural person resident in Hong Kong, or an accounting professional, legal professional or licensed TCSP. The report states that law-enforcement access for lawful functions does not require a court order; this does not confer the same access power on an MSO.'),
 ('海關指引註27明確容許MSO參閱這類登記冊以協助識別實益擁有人；如資料不公開，可直接向客戶索取紀錄。仍須按本節核實及了解擁有權／控制結構，不能把取得SCR當作完成全部CDD。','Customs Guideline note 27 expressly permits reference to such registers to assist identification of beneficial owners; where not public, the MSO may obtain the record directly from the customer. The verification and ownership/control analysis in this section still apply; obtaining an SCR is not completion of all CDD.'),
],[ref('25','2022年版，第7.20、7.24–7.27段及註201','2022 edition, ¶7.20, 7.24–7.27 and note 201','Significant controllers include'),ref('03','第4.4.3–4.4.4段及註27','¶4.4.3–4.4.4 and note 27','An MSO may refer to such registers')],'補公司控制資料的用途、完整擇一條件與MSO責任界線。')

# Replace the vague asset-protection phrase without disturbing the licence/penalty point.
vb=sec(2,'other-sector-regimes')['blocks'][1]
for point in vb['points']:
    for lang in ('tc','en'):
        if lang=='tc':point[lang]=point[lang].replace('客戶資產受獨立保障；','')
        else:point[lang]=point[lang].replace('Client assets have separate protection; ','')
add('O09',2,'other-sector-regimes','參考：虛擬資產客戶資產的保障界線','Reference: limits of VA client-asset protection',[
 ('第53ZRT條：在針對持牌提供者或其有聯繫實體執行法庭命令／程序文件時，不得取去該提供者的客戶資產。但任何人對該等資產享有的合法申索權或留置權不因此被剝奪／影響；存在申索權或留置權也不免除提供者／有聯繫實體遵守適用守則及指引的責任。這並非保證客戶資產在所有情況下都不受任何申索。','Section 53ZRT prevents client assets of a licensed provider being taken in execution of court orders/process against the provider or its associated entity. It preserves any person’s lawful claim or lien over those assets; such a claim/lien does not relieve the provider/associated entity of applicable code/guideline duties. This is not immunity of client assets from every possible claim.'),
],[ref('04','第53ZRT條','s.53ZRT','Client assets of a licensed provider are not liable')],'以具體保障、權利保留及不獲豁免的義務取代籠統表述。','reference')

add('O10',2,'other-sector-regimes','參考：虛擬資產欺詐的兩項罪行','Reference: two VA fraud offences',[
 ('第53ZRF條適用於任何人在涉及虛擬資產的交易中，直接／間接出於欺詐或欺騙意圖使用手段、計劃或計謀，或從事具欺詐／欺騙性質或效果的作為、做法或業務；交易包括要約及邀請。循公訴最高罰款1,000萬元及監禁10年；循簡易程序最高100萬元及3年。法庭另可禁止其未經法庭許可在港買賣／處理虛擬資產，期間最長5年。不是只有無牌交易所才可能觸犯。','Section 53ZRF covers any person directly/indirectly using a device, scheme or artifice with intent to defraud/deceive, or engaging in fraudulent/deceptive acts, practices or business, in a VA transaction, including offers/invitations. Maximum penalties are HK$10 million/10 years on indictment, or HK$1 million/three years summarily. The court may also prohibit Hong Kong VA dealing without its leave for up to five years. The offence is not confined to unlicensed exchanges.'),
 ('第53ZRG條另針對為誘使另一人訂立或要約訂立取得、處置、認購或包銷VA協議，而作欺詐或罔顧實情的失實陳述。範圍包括虛假／誤導陳述、無法履行的承諾、按當時已知事實沒有充分理由支持的預測及遺漏重要事實；須符合該條的知情、故意或罔顧實情要件，欺詐承諾也包括根本無意履行。循公訴最高100萬元及7年；循簡易程序最高第6級罰款及6個月。不能把投資虧損本身直接當成此罪。','Section 53ZRG separately covers fraudulent/reckless misrepresentations made to induce an agreement, or offer to agree, to acquire, dispose of, subscribe for or underwrite VAs. Its definitions include false/misleading statements, unfulfillable promises, forecasts unjustified on facts then known and material omissions, subject to the specified knowledge, intention or recklessness elements; fraudulent promises also include those made without intent to fulfil. Maximum penalties are HK$1 million/seven years on indictment, or level 6/six months summarily. Investment loss alone is not the offence.'),
],[ref('04','第53ZRF–53ZRG條','ss.53ZRF–53ZRG','Offence to fraudulently or recklessly induce others')],'補無牌經營以外的重要行為禁令，保留精神要件。','reference')

add('O11',2,'other-sector-regimes','參考：證監會的跨境VA合作條件','Reference: SFC cross-border VA cooperation conditions',[
 ('第13B條的執法合作，是應境外監管者要求，調查與第11(1)(a)／(d)條事項性質相似的境外VA違規；第13C條的監管合作，則協助判斷受對方規管的持牌VA提供者或其有關連法團，是否影響對方金融穩定或遵守／能遵守當地VA規定。不是境外監管者可直接向任何MSO行使同一權力。','Section 13B enforcement cooperation assists, at an overseas regulator’s request, investigation of overseas VA contraventions similar in nature to section 11(1)(a)/(d) matters. Section 13C supervisory cooperation concerns financial stability or VA compliance/capacity to comply of an overseas-regulated licensed VA provider or its related corporation. This is not the same power exercisable directly by an overseas regulator over any MSO.'),
 ('兩種合作均須證監會認為：對方履行類似職能或規管／監督／調查指定金融服務，並受充分保密規定約束；而提供協助對投資者／公眾利益屬適宜或權宜，或有助對方履職且不違反上述利益。費用承擔及能否／是否願意互惠協助是必須考慮的因素，不是另加兩項絕對先決條件。','Both require the SFC’s opinion that the regulator performs similar functions OR regulates/supervises/investigates specified financial services, AND is subject to adequate secrecy requirements; assistance must be desirable/expedient in investors’/public interests OR help the regulator’s functions without being contrary to those interests. Cost contribution and ability/willingness to reciprocate are mandatory considerations, not two additional absolute prerequisites.'),
 ('監管合作另須書面確認：沒有其他合理方法取得資料，且欠缺資料便不能全面確定所查事項；並書面承諾僅作該監管用途、保密及未經證監會同意不向他人披露。不得用於法律程序，除非另依第13B條提出要求、獲證監會決定協助並循該次要求取得相同資料。收到可依法強制披露的要求時，須盡快通知證監會、採可用的適當保密措施，並配合保障保密的行動。','Supervisory cooperation additionally requires written confirmation that no other reasonable means can obtain the information AND the matters cannot be fully ascertained without it; and written undertakings limiting use to that supervisory purpose, confidentiality and no onward disclosure without SFC consent. Proceedings use requires a separate section 13B request, an SFC decision to assist, and obtaining the same information under that request. Legally enforceable disclosure demands require prompt SFC notification, available appropriate confidentiality measures and cooperation in confidentiality-protection actions.'),
 ('執法合作中，如被強制提供的解釋／詳情／回答可能使本人入罪，且本人提供前已如此聲稱，第13B(8)條禁止把該要求或資料的證據交予對方，用於當地針對本人的刑事法律程序；調查人員須先告知／提醒該用途限制。不能誤記為可以拒絕一切資料要求，或任何資料一律不得交換。','In enforcement cooperation, if compelled explanations, particulars or answers might incriminate the person AND the person claims this before giving them, section 13B(8) bars providing evidence of the requirement/information for criminal proceedings against that person in that jurisdiction. The investigator must first inform/remind the person of this use limitation. This is neither a blanket refusal right nor a ban on every information exchange.'),
],[ref('04','第13A–13E條','ss.13A–13E','International supervisory cooperation')],'整個跨境合作分部原先未說明；補用途、AND／OR及資料保障，仍列其他行業參考。','reference')

add('O12',2,'other-sector-regimes','參考：非香港DPMS現金報告須提供甚麼','Reference: contents of a non-Hong Kong DPMS cash report',[
 ('上述非香港DPMS指明現金交易報告的附表3J資料有四組：交易商基本資料；每名第53ZVK(4)條指明個人的行程；交易詳情；客戶基本資料。行程包括抵港前上一港口、預定離港後下一港口、抵港及預定離港日期、進出交通工具詳情。交易詳情包括日期、所交易物品／資產支持工具的描述、每項或多項現金付款金額及交易地點地址。','Schedule 3J has four groups for the non-Hong Kong DPMS specified-cash-transaction report above: dealer basic information; travel information for each specified individual under section 53ZVK(4); transaction information; customer basic information. Travel covers last port before arrival, scheduled next port, arrival/scheduled departure dates and transport details. Transaction details cover date, descriptions of items/asset-backed instruments traded, cash payment amount(s) and transaction address.'),
 ('基本資料按人別分開：個人須全名、旅行證件號碼及簽發地、國籍、出生日期／地點、居籍／永久居留地及香港地址；非個人須名稱、主要營業地點地址，法團另須成立地的註冊辦事處地址，如成立後遷冊則用最新本籍地的註冊辦事處地址。','Basic information depends on the person: individuals require full name, travel-document number/place of issue, nationality, birth date/place, domicile/permanent residence and Hong Kong address. Non-individuals require name and principal business address; corporations additionally require their registered-office address in the place of incorporation, or latest domicile after a subsequent domicile change.'),
 ('非個人的基本資料亦須包括每名在交易中代其行事者的全名、識別文件號碼（旅行證件另列簽發地）、代表交易商行事的身分及香港地址。這是該特別報告的資料清單，不是要求所有MSO客戶一律提交旅行行程。','Non-individual basic information also includes each individual acting for it in the transaction: full name, identification-document number (and travel-document place of issue where applicable), capacity in which the individual acted for the dealer, and Hong Kong address. This is the special report’s information list, not a requirement for every MSO customer to provide an itinerary.'),
],[ref('04','第53ZVK條；附表3J第1–2條','s.53ZVK; Schedule 3J ss.1–2','Information to be Provided in Cash Transaction Report')],'已教報告期限但未解釋報甚麼；補具體內容並限於該非香港交易商制度。','reference')

def emit(n,v):
    pair=lambda x:'p('+repr(x['tc'])+', '+repr(x['en'])+')'
    lines=['"""Source-authored bilingual manuscript; source-checked 2026-10-19. No bank input."""','from model import p, ref, block, section','','PART = dict(title='+pair(v['title'])+',','intro='+pair(v['intro'])+', sections=[']
    for s in v['sections']:
        lines.append('section('+repr(s['id'])+', '+repr(s['title']['tc'])+', '+repr(s['title']['en'])+', [')
        for b in s['blocks']:
            lines.append('    block('+repr(b['title']['tc'])+', '+repr(b['title']['en'])+', [')
            for x in b['points']:lines.append('        ('+repr(x['tc'])+', '+repr(x['en'])+'),')
            lines.append('    ], [')
            for r in b['refs']:lines.append('        ref('+', '.join(repr(x) for x in [r['doc'],r['locator']['tc'],r['locator']['en'],r['anchor']])+'),')
            lines.append('    ], kind='+repr(b['kind'])+'),')
        lines.append(']),')
    lines.append('])\n')
    (NOTES/f'part{n}.py').write_text('\n'.join(lines),encoding='utf-8')
assert not (HERE/'findings.json').exists(),'Do not overwrite completed evidence'
for n in (1,2,6,7):emit(n,parts[n])
(HERE/'findings.json').write_text(json.dumps(findings,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Applied',len(findings),'source-authored omission groups')
